          "description": "Requisitos O carniçal está adjacente ao cadáver de uma criatura que morreu na última hora.\nEfeito O carniçal devora um pedaço do cadáver e recupera 1d6[cura] Pontos de Vida.\nEle pode recuperar Pontos de Vida de qualquer cadáver apenas uma vez."
