          "name": "Sussurros de Carniçais",
          "description": "Requisitos Uma criatura agarrada, paralisada, contida ou inconsciente está ao alcance do carniçal\nEfeito O carniçal sussurra pensamentos sombrios e desejos vis nos ouvidos da criatura. A criatura deve se salvar contra a maldição dos desejos proibidos.\nDesejos Proibidos (maldição) Uma criatura ainda pode comer e beber enquanto estiver doente por esta maldição\nTeste de teste de resistência (vontade, dc:17, características: maldição)\nPortador de estágio 1 sem efeitos nocivos (1 dia)\nEstágio 2 2d6[void] de dano e o alvo fica Enjoado 1 até consumir carne crua (1 dia)\nEstágio 3 como estágio 2\nEstágio 4 como estágio 2, a menos que o alvo tenha consumido carne crua nas últimas 24 horas, então ele sofre 4d6[void] de dano e fica Enjoado 2 até consumir carne crua;\nEstágio 5 se a criatura comeu carne crua nas últimas 24 horas, ela morre e ressuscita como um ghoul, caso contrário, retorna ao estágio 4"
