      "name": "Encrenqueiro Halfling",
      "description": "A bravata de um halfling às vezes pode levá-los a problemas. Esses trapaceiros costumam vagar em grupos tentando superar a última pegadinha uns dos outros. Embora os encrenqueiros raramente tenham a intenção de matar, ocasionalmente suas travessuras ficam fora de controle.\nApesar de sua pequena estatura, um halfling pode ser um inimigo poderoso se você estiver do lado errado da frigideira.",
