        "upfgXZWcGklPhe0Z": {
          "name": "Ovo Grafite",
          "description": "O encrenqueiro halfling joga um ovo cheio de tinta, purpurina e confete em uma criatura dentro de 30 pés (9 metros). O alvo deve ser bem sucedido em um teste de resistência (reflexo, dc:17, opções:infligir:deslumbrado) ou ficará Deslumbrado por 1 rodada (ou 1 minuto em caso de falha crítica)."
        },
        "BoBYJI6l42pBuF55": {
          "name": "Olhos Aguçados",
          "description": "O halfling ganha um bônus de circunstância de +2 ao usar a ação Procurar para encontrar criaturas Ocultas ou Não Detectadas dentro de 30 pés (9 metros) dele.\nSempre que o halfling mirar em uma criatura que esteja Oculta ou escondida dele, reduza a CD do teste simples para verificar (simples, dc:3) para um alvo oculto ou teste (simples, dc:9) para um alvo oculto."
        },
