        "xJGiCaAnnERzWXes": {
          "name": "Alterar forma",
          "description": "O raktavarna assume a aparência de um minúsculo objeto inanimado. Se, enquanto transformado, o raktavarna realizar qualquer ação que não seja puramente mental (como Recuperar Conhecimento), ele imediatamente reverterá à sua forma original. Até então, eles podem usar Deception para personificar o objeto."
        },
        "IE75LW4gCgc5TOPJ": {
          "name": "Designar Mestre",
          "description": "O raktavarna gasta 10 minutos em uma invocação ao lado de outra criatura. Aquela criatura se torna o mestre do raktavarna até que o raktavarna morra ou rejeite o efeito. O mestre ganha a atividade Olhos do Mestre enquanto durar o vínculo.\nOlho do Mestre"
        },
