      "name": "Elfo Ranger",
      "description": "Muitos elfos aprendem a usar o arco antes mesmo de pegar sua primeira lâmina. Por causa disso, muitos elfos atuam como rangers em algum momento de suas longas vidas.\nElfos são misteriosos e inteligentes, além de graciosos e astutos em batalha.",
