          "description": "Teste de salvamento (fortitude, dc:16)\nDuração Máxima 6 rodadas\nEstágio 1 1d4[veneno] de dano e Enfraquecido 1 (1 rodada)\nEstágio 2 2d4[veneno] de dano e debilitado 1 (1 rodada)"
