      "description": "Bonecas ligadas à alma são manequins ou brinquedos misteriosos que foram imbuídos de um pequeno pedaço da alma de um mortal falecido. Essas pequenas construções são criadas por vários motivos – como servir como companheiros ou servos – mas seu livre arbítrio significa que sua obediência aos seus criadores dificilmente é garantida. Os seguidores de Pharasma geralmente abominam bonecos vinculados à alma, vendo-os como uma perversão do ciclo natural das almas, e aqueles que adoram a Senhora dos Túmulos veem a destruição de um boneco vinculado à alma, independentemente do comportamento do construto, como um serviço importante para o Grande Além.\nBonecos com almas são os mais simples de uma série de construções com almas, incluindo manequins com almas de tamanho humano, poderosas conchas com almas e guerreiros sentinelas de terracota com almas. Criá-los a partir de criaturas vivas relutantes é cruel, e um doador relutante pode resistir ao processo com um teste bem-sucedido de Vontade contra a CD de Ofícios do criador, arruinando a boneca se não evitar a morte do doador. Uma boneca também pode ser feita a partir da alma de uma pessoa que deu consentimento para tal uso antes de sua morte.\nBonecos vinculados à alma encontrados por aventureiros são normalmente algum tipo de guardiões; apesar de seu tamanho diminuto, o poder do fragmento de alma torna o punho da boneca mais perigoso do que um observador casual esperaria. Além disso, concede à boneca um único magia de poder descomunal, dada a sua estatura. Devido à sua autonomia e inteligência notável, os bonecos vinculados à alma são ocasionalmente empregados por seus artesãos como administradores de construções muito mais poderosas, mas estúpidas, permitindo que tais bonecos controlem defesas muito além de suas próprias capacidades.\nEmbora os bonecos vinculados à alma contenham um pequeno fragmento de uma alma extraída durante ou logo após a morte de uma pessoa, isso não afeta a ressurreição do falecido ou o progresso para a vida após a morte. Este processo de extração é normalmente letal para possíveis doadores de almas vivos.\nO fragmento da alma reside em uma gema de foco da alma (Dureza 10) normalmente incrustada no pescoço ou no peito da boneca. O fragmento de alma geralmente se apega a um forte traço de personalidade da alma original, mas a boneca continua a aprender com seu estado inicial, o que significa que sua personalidade e habilidades podem mudar, possivelmente se aproximando do doador ou se afastando em seu próprio caminho individual. A gema de foco da boneca vinculada à alma retém as memórias da boneca mesmo após sua destruição. A gema intacta do foco da alma de uma boneca destruída pode até ser colocada em um novo corpo de boneca por alguém com conhecimento na criação de criaturas vinculadas à alma, reconstituindo efetivamente a boneca vinculada à alma.",
