      "name": "Elementalista Aiuvarin",
      "description": "Comumente chamados de meio-elfos, os aiuvarins costumam ter problemas para se adaptar à sociedade. Isso pode fazer com que muitos aiuvarins desviem toda a sua atenção para suas atividades pessoais, como estudar conjuração de magias.\nElfos são misteriosos e inteligentes, além de graciosos e astutos em batalha.",
