          "description": "Uma criatura atingida pelas mandíbulas de uma cria do pecado deve tentar um teste (vontade, dc:18) para salvar, pois é atacada por pensamentos pecaminosos.\nSucesso crítico não afetado\nSucesso Enjoado 1\nFalha Enjoada 2\nFalha Crítica adoeceu 2 mais – penalidade de status de 10 pés em suas Velocidades por 1 minuto\nEfeito: Mordida Pecaminosa"
