        "jmPDVPebOQ3XVOwA": {
          "name": "Carga de Javali",
          "description": "O javali dá dois passos e depois dá um golpe de presa. Contanto que ele se mova pelo menos 20 pés (6 metros), ele ganha +2 de bônus de circunstância em sua jogada de ataque."
        }
